bool MemsetMemcpyLauncher::MemOpWrite32()
{
    CUstream stream = nullptr;
    const uint32_t value = 0x76543210ull;
    CUresult result = cuStreamWriteValue32(stream, (CUdeviceptr)m_pDeviceBufferDst, value, 0);
    if (result != CUDA_SUCCESS)
