    CUDA_SAFE_CALL((cudaStreamBeginCapture(m_stream, cudaStreamCaptureModeGlobal)), m_errorMsg);

    CUresult result = cuMemcpyAsync(
        reinterpret_cast<CUdeviceptr>(m_pPinnedBufferDst),
