    CUDA_SAFE_CALL((cudaStreamEndCapture(m_stream, &m_graph)), m_errorMsg);
    CUDA_SAFE_CALL((cudaGraphInstantiate(&m_graphExec, m_graph, nullptr, nullptr, 0)), m_errorMsg);
    return true;
}

