    GTEST_ASSERT_(::testing::internal::EqHelper::Compare("cudaSuccess", pExpr, cudaSuccess, error), GTEST_NONFATAL_FAILURE_)
        << "cudaError=" << cudaGetErrorName(error) << " : " << cudaGetErrorString(error);
}

